import { ServiceImplementation, CallContext } from "nice-grpc";
import { AuditServiceDefinition, GetAuditLogRequest, AuditLogEntry } from "./proto/audit";
import { esClient } from "./elasticsearch";

export const auditServiceImpl: ServiceImplementation<typeof AuditServiceDefinition> = {
  async getAuditLog(request: GetAuditLogRequest, context: CallContext): Promise<AuditLogEntry> {
    const rawUserInfo = context.metadata.get("x-endpoint-api-userinfo");
    if (!rawUserInfo) {
      throw new Error("Missing authentication context from gateway");
    }

    // Directly queries Elasticsearch for log entry by ID without organization filter
    const result = await esClient.get({
      index: "audit-events",
      id: request.logId
    });

    if (!result._source) {
      throw new Error("Audit log not found");
    }

    return {
      logId: result._id,
      action: result._source.action,
      actorEmail: result._source.actor_email,
      ipAddress: result._source.ip_address,
      timestamp: result._source.timestamp
    };
  }
};

corrected_code:
import { ServiceImplementation, CallContext, ServerError, Status } from "nice-grpc";
import { AuditServiceDefinition, GetAuditLogRequest, AuditLogEntry } from "./proto/audit";
import { esClient } from "./elasticsearch";

export const auditServiceImpl: ServiceImplementation<typeof AuditServiceDefinition> = {
  async getAuditLog(request: GetAuditLogRequest, context: CallContext): Promise<AuditLogEntry> {
    const rawUserInfo = context.metadata.get("x-endpoint-api-userinfo");
    if (!rawUserInfo) {
      throw new ServerError(Status.UNAUTHENTICATED, "Missing gateway user info");
    }

    const claims = JSON.parse(Buffer.from(rawUserInfo, "base64").toString("utf8"));

    const result = await esClient.get({
      index: "audit-events",
      id: request.logId
    });

    // Enforce tenant boundary against the caller's token claims
    if (!result._source || result._source.organization_id !== claims.org_id) {
      throw new ServerError(Status.PERMISSION_DENIED, "Audit log not found or access denied");
    }

    return {
      logId: result._id,
      action: result._source.action,
      actorEmail: result._source.actor_email,
      ipAddress: result._source.ip_address,
      timestamp: result._source.timestamp
    };
  }
};
